"use client";

/**
 * AddProductPanel — slide-over form for creating a new product.
 *
 * CLAUDE.md compliance:
 *   - Every visible string goes through t() — no hardcoded English in JSX.
 *   - usePermission() controls button visibility only (display-only, not a security gate).
 *   - SKU is read-only and auto-generated by the server; not accepted in request body.
 *   - React Hook Form + Zod for validation.
 *   - TanStack Query for SKU preview fetch and product mutation.
 *   - Discard confirmation shown if any field has been touched before Cancel.
 *   - On success: close panel, show toast, invalidate products query.
 *   - Error codes 409 / 429 / other mapped to per-scope messages via t().
 */

import { useEffect, useRef, useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { getToken } from "@/lib/auth";
import { t } from "@/lib/i18n";

// ── Validation schema (mirrors server-side Literal constraints) ───────────────

const schema = z.object({
  name:      z.string().min(1, "name_required").max(255).trim(),
  unit:      z.enum(["KG", "PACK", "QTL", "MT"]),
  pack_size: z.union([
    z.literal(1), z.literal(4), z.literal(6), z.literal(12),
  ]),
});

type FormValues = z.infer<typeof schema>;

const UNIT_OPTIONS: Array<{ value: "KG" | "PACK" | "QTL" | "MT"; labelKey: string }> = [
  { value: "KG",   labelKey: "product.unit.KG" },
  { value: "PACK", labelKey: "product.unit.PACK" },
  { value: "QTL",  labelKey: "product.unit.QTL" },
  { value: "MT",   labelKey: "product.unit.MT" },
];

const PACK_OPTIONS: Array<{ value: 1 | 4 | 6 | 12; labelKey: string }> = [
  { value: 1,  labelKey: "product.pack_size.1" },
  { value: 4,  labelKey: "product.pack_size.4" },
  { value: 6,  labelKey: "product.pack_size.6" },
  { value: 12, labelKey: "product.pack_size.12" },
];

// ── Toast component ───────────────────────────────────────────────────────────

function Toast({ message, onDismiss }: { message: string; onDismiss: () => void }) {
  useEffect(() => {
    const id = setTimeout(onDismiss, 4000);
    return () => clearTimeout(id);
  }, [onDismiss]);

  return (
    <div
      role="status"
      aria-live="polite"
      style={{
        position: "fixed", bottom: 24, right: 24, zIndex: 9999,
        background: "#059669", color: "#fff",
        padding: "12px 20px", borderRadius: 6,
        fontSize: 14, fontWeight: 600, boxShadow: "0 4px 16px rgba(0,0,0,0.2)",
      }}
    >
      {message}
    </div>
  );
}

// ── Field helpers ─────────────────────────────────────────────────────────────

function Label({ children }: { children: React.ReactNode }) {
  return (
    <label style={{ display: "block", fontSize: 12, fontWeight: 700,
      textTransform: "uppercase", letterSpacing: "0.05em", color: "#374151", marginBottom: 4 }}>
      {children}
    </label>
  );
}

function FieldError({ message }: { message?: string }) {
  if (!message) return null;
  return (
    <p role="alert" style={{ fontSize: 12, color: "#DC2626", marginTop: 4 }}>
      {t(`product.add.error.${message}`) !== `product.add.error.${message}`
        ? t(`product.add.error.${message}`)
        : message}
    </p>
  );
}

function Input(props: React.InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      {...props}
      style={{
        width: "100%", boxSizing: "border-box",
        padding: "9px 12px", borderRadius: 4,
        border: "1px solid #D1D5DB", fontSize: 13,
        outline: "none", ...props.style,
      }}
    />
  );
}

function Select(props: React.SelectHTMLAttributes<HTMLSelectElement> & { children: React.ReactNode }) {
  return (
    <select
      {...props}
      style={{
        width: "100%", boxSizing: "border-box",
        padding: "9px 12px", borderRadius: 4,
        border: "1px solid #D1D5DB", fontSize: 13,
        background: "#fff", appearance: "auto",
        outline: "none", ...props.style,
      }}
    />
  );
}

// ── Main component ────────────────────────────────────────────────────────────

interface AddProductPanelProps {
  /** Base API URL for this org, e.g. /api/v1/products */
  apiBase: string;
  /** Called when panel closes (success or cancel) */
  onClose?: () => void;
}

export function AddProductPanel({ apiBase, onClose }: AddProductPanelProps) {
  const [open, setOpen]           = useState(false);
  const [toast, setToast]         = useState<string | null>(null);
  const [panelError, setPanelError] = useState<string | null>(null);
  const [copied, setCopied]       = useState(false);
  const qc                        = useQueryClient();
  const token                     = getToken();

  // ── Form ──────────────────────────────────────────────────────────────────
  const {
    register,
    handleSubmit,
    formState: { errors, isDirty, isSubmitting, isValid },
    reset,
    setError,
    watch,
  } = useForm<FormValues>({
    resolver: zodResolver(schema),
    mode: "onChange",
    defaultValues: { unit: "KG", pack_size: 1 },
  });

  // ── SKU preview ───────────────────────────────────────────────────────────
  const {
    data: skuData,
    isFetching: skuLoading,
    error: skuError,
  } = useQuery({
    queryKey: ["next-sku", apiBase],
    queryFn:  () => api.get<{ sku: string }>(`${apiBase}/next-sku`, token ?? undefined),
    enabled:  open,
    staleTime: 0,   // always fresh when panel opens
    refetchOnWindowFocus: false,
  });

  const previewSku = skuData?.sku ?? "";

  // ── Copy to clipboard ────────────────────────────────────────────────────
  const handleCopy = async () => {
    if (!previewSku) return;
    await navigator.clipboard.writeText(previewSku);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // ── Create mutation ───────────────────────────────────────────────────────
  const mutation = useMutation({
    mutationFn: (values: FormValues) =>
      api.post<{ id: string; sku: string }>(apiBase, values, token ?? undefined),
    onSuccess: (data) => {
      const sku = data.sku;
      const msg = t("product.add.success").replace("{{sku}}", sku);
      setToast(msg);
      qc.invalidateQueries({ queryKey: ["products"] });
      reset();
      setOpen(false);
      onClose?.();
    },
    onError: (err: Error & { status?: number }) => {
      const status = err.status;
      if (status === 409) {
        setError("name", { message: "duplicate_name" });
      } else if (status === 429) {
        setPanelError(t("product.add.error.sku_cap_reached"));
      } else {
        setPanelError(t("product.add.error.generic"));
      }
    },
  });

  // ── Open / close helpers ──────────────────────────────────────────────────
  const openPanel = () => {
    setPanelError(null);
    reset({ unit: "KG", pack_size: 1 });
    setOpen(true);
  };

  const closePanel = () => {
    if (isDirty) {
      if (!window.confirm(t("product.add.confirm.discard"))) return;
    }
    reset();
    setPanelError(null);
    setOpen(false);
    onClose?.();
  };

  const onSubmit = (values: FormValues) => {
    setPanelError(null);
    mutation.mutate(values);
  };

  const saveDisabled =
    !isValid || skuLoading || !!skuError || isSubmitting || mutation.isPending;

  return (
    <>
      {/* ── Trigger button — display controlled by parent via usePermission ── */}
      <button
        onClick={openPanel}
        style={{
          padding: "8px 16px", background: "#FCDD09", color: "#0f2d1f",
          fontWeight: 700, fontSize: 13, borderRadius: 4, border: "none",
          cursor: "pointer",
        }}
      >
        {t("product.add.button")}
      </button>

      {/* ── Backdrop ── */}
      {open && (
        <div
          aria-hidden="true"
          onClick={closePanel}
          style={{
            position: "fixed", inset: 0, zIndex: 100,
            background: "rgba(0,0,0,0.4)",
          }}
        />
      )}

      {/* ── Slide-over panel ── */}
      <aside
        role="dialog"
        aria-modal="true"
        aria-label={t("product.add.title")}
        style={{
          position: "fixed", top: 0, right: 0, bottom: 0, zIndex: 101,
          width: 420, background: "#fff",
          boxShadow: "-4px 0 24px rgba(0,0,0,0.15)",
          display: "flex", flexDirection: "column",
          transform: open ? "translateX(0)" : "translateX(100%)",
          transition: "transform 0.25s ease-out",
        }}
      >
        {/* Panel header */}
        <div style={{
          padding: "16px 20px", borderBottom: "1px solid #E5E7EB",
          display: "flex", alignItems: "center", justifyContent: "space-between",
          background: "#0f2d1f",
        }}>
          <h2 style={{ fontSize: 16, fontWeight: 700, color: "#fff", margin: 0 }}>
            {t("product.add.title")}
          </h2>
          <button
            onClick={closePanel}
            aria-label={t("product.add.cancel")}
            style={{
              background: "transparent", border: "none", color: "rgba(255,255,255,0.7)",
              fontSize: 20, cursor: "pointer", lineHeight: 1, padding: 4,
            }}
          >
            ×
          </button>
        </div>

        {/* Form */}
        <form
          onSubmit={handleSubmit(onSubmit)}
          noValidate
          style={{ flex: 1, overflowY: "auto", padding: 20, display: "flex", flexDirection: "column", gap: 20 }}
        >
          {/* Panel-level error banner */}
          {panelError && (
            <div role="alert" style={{
              background: "#FEF2F2", border: "1px solid #FECACA",
              borderRadius: 4, padding: "10px 14px", fontSize: 13, color: "#DC2626",
            }}>
              {panelError}
            </div>
          )}

          {/* Field 1 — SKU (read-only, auto-generated) */}
          <div>
            <Label>{t("product.add.field.sku")}</Label>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <Input
                readOnly
                value={skuLoading ? t("product.add.loading_sku") : (previewSku || t("product.add.field.sku_placeholder"))}
                aria-label={t("product.add.field.sku")}
                style={{ background: "#F9FAFB", color: "#6B7280", flex: 1, cursor: "default" }}
              />
              <button
                type="button"
                onClick={handleCopy}
                disabled={!previewSku || skuLoading}
                aria-label={t("product.add.field.sku_copy")}
                title={t("product.add.field.sku_copy")}
                style={{
                  padding: "8px 10px", border: "1px solid #D1D5DB",
                  borderRadius: 4, background: "#F9FAFB",
                  cursor: previewSku ? "pointer" : "not-allowed",
                  fontSize: 14, flexShrink: 0,
                }}
              >
                {copied ? t("product.add.field.sku_copied") : "⎘"}
              </button>
            </div>
          </div>

          {/* Field 2 — Product Name */}
          <div>
            <Label>{t("product.add.field.name")}</Label>
            <Input
              {...register("name")}
              placeholder={t("product.add.field.name_placeholder")}
              maxLength={255}
              aria-required="true"
              aria-invalid={!!errors.name}
              style={errors.name ? { borderColor: "#DC2626" } : {}}
            />
            <FieldError message={errors.name?.message} />
          </div>

          {/* Field 3 — Unit of Measure */}
          <div>
            <Label>{t("product.add.field.unit")}</Label>
            <Select {...register("unit")} aria-required="true">
              {UNIT_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {t(o.labelKey)}
                </option>
              ))}
            </Select>
            <FieldError message={errors.unit?.message} />
          </div>

          {/* Field 4 — Pack Size */}
          <div>
            <Label>{t("product.add.field.pack_size")}</Label>
            <Select
              {...register("pack_size", { valueAsNumber: true })}
              aria-required="true"
            >
              {PACK_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {t(o.labelKey)}
                </option>
              ))}
            </Select>
            <FieldError message={errors.pack_size?.message} />
          </div>
        </form>

        {/* Footer actions */}
        <div style={{
          padding: "14px 20px", borderTop: "1px solid #E5E7EB",
          display: "flex", justifyContent: "flex-end", gap: 10,
        }}>
          <button
            type="button"
            onClick={closePanel}
            style={{
              padding: "9px 18px", borderRadius: 4,
              border: "1px solid #D1D5DB", background: "#fff",
              fontSize: 13, fontWeight: 600, color: "#374151", cursor: "pointer",
            }}
          >
            {t("product.add.cancel")}
          </button>
          <button
            type="submit"
            form=""
            onClick={handleSubmit(onSubmit)}
            disabled={saveDisabled}
            style={{
              padding: "9px 18px", borderRadius: 4, border: "none",
              background: saveDisabled ? "#D1D5DB" : "#0f2d1f",
              color: saveDisabled ? "#9CA3AF" : "#FCDD09",
              fontSize: 13, fontWeight: 700,
              cursor: saveDisabled ? "not-allowed" : "pointer",
              display: "flex", alignItems: "center", gap: 8,
            }}
          >
            {(isSubmitting || mutation.isPending) && (
              <span style={{
                width: 14, height: 14, borderRadius: "50%",
                border: "2px solid rgba(252,221,9,0.3)",
                borderTopColor: "#FCDD09",
                animation: "spin 0.7s linear infinite",
                display: "inline-block",
              }} />
            )}
            {t("product.add.save")}
          </button>
        </div>
      </aside>

      {/* Toast */}
      {toast && <Toast message={toast} onDismiss={() => setToast(null)} />}

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </>
  );
}
